/**
 * ColorAdjust: brightness, saturation and a colour tint, via a colour-matrix filter.
 *
 * Generated by Pixi Editor (components v1). Plain TypeScript: safe to read, edit and commit.
 */
import { ColorMatrixFilter, type Filter } from "pixi.js";
import { Component } from "../core";
import { clearFilter, setFilter } from "./filter-stack";

export interface ColorAdjustParams {
  /** 1 = unchanged, below 1 darker, above 1 brighter. */
  brightness: number;
  /** 1 = unchanged, 0 = greyscale, above 1 = more saturated. */
  saturation: number;
  /** A colour multiplied over the object (0xffffff = none). */
  tint: number;
}

/** Adjusts the object's brightness, saturation and tint. Stacks with other filter components. */
export class ColorAdjust extends Component<ColorAdjustParams> {
  static readonly componentName = "ColorAdjust";
  static readonly defaults: ColorAdjustParams = {
    brightness: 1,
    saturation: 1,
    tint: 0xffffff,
  };

  private filter: Filter | null = null;

  apply(): void {
    const f = new ColorMatrixFilter();
    f.brightness(this.params.brightness, false);
    f.saturate(this.params.saturation - 1, true); // saturate(0) leaves it unchanged
    if (this.params.tint >>> 0 !== 0xffffff) f.tint(this.params.tint, true);
    setFilter(this.target, this.filter, f);
    this.filter = f;
  }

  detach(): void {
    clearFilter(this.target, this.filter);
    this.filter = null;
  }
}
